package com.shiphappens.logistics.config;
import com.shiphappens.logistics.dto.Requests; import com.shiphappens.logistics.entity.*; import com.shiphappens.logistics.entity.Statuses.*; import com.shiphappens.logistics.repository.*; import com.shiphappens.logistics.service.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.core.annotation.Order; import java.math.BigDecimal; import java.util.List;
@Configuration public class DemoDataConfiguration {
 @Bean @Order(1) CommandLineRunner safeDemoData(CustomerRepository customers,DriverRepository drivers,VehicleRepository vehicles,LogisticsService service){return args->{if(customers.count()>0)return; Customer customer=service.createCustomer(new Requests.Customer("CUST-DEMO","Demo Commerce","ops@demo.invalid","+91 90000 00000")); Driver driver=new Driver();driver.setDriverCode("DRV-DEMO-01");driver.setName("Aarav Demo");driver.setPhone("+91 90000 00001");driver.setLicenseNumber("DEMO-LIC-001");drivers.save(driver);Vehicle vehicle=new Vehicle();vehicle.setVehicleNumber("DEMO-TRUCK-01");vehicle.setVehicleType("Box truck");vehicle.setCapacityKg(new BigDecimal("1500"));vehicles.save(vehicle);Shipment shipment=service.createOrder(new Requests.CreateOrder(customer.getId(),new Requests.Address("100 Demo Warehouse Road",null,"Hyderabad","Telangana","500001","India"),new Requests.Address("42 Fictional Avenue",null,"Bengaluru","Karnataka","560100","India"),List.of(new Requests.Package("Demo electronics",new BigDecimal("5.50"),new BigDecimal("30"),new BigDecimal("20"),new BigDecimal("15"),new BigDecimal("12000")))),"DEMO-EXT-1001");service.updateShipment(shipment.getId(),new Requests.ShipmentStatus(ShipmentStatus.PICKED_UP,"Hyderabad","Demo pickup completed"));service.updateShipment(shipment.getId(),new Requests.ShipmentStatus(ShipmentStatus.IN_TRANSIT,"NH 44","Demo shipment in transit"));};}
 @Bean @Order(2) CommandLineRunner optionalDemoAdmin(AuthService auth,AppUserRepository users,@Value("${app.security.demo-password:}") String password){return args->{if(!password.isBlank()&&users.findByEmail("demo@shiphappens.app").isEmpty())auth.register("demo@shiphappens.app",password,UserRole.ADMIN);};}
}
